from abc import ABCMeta, abstractmethod
from os import makedirs
import six


@six.add_metaclass(ABCMeta)
class TtiCollectorInterface:
    @abstractmethod
    def __init__(self):
        pass

    @abstractmethod
    def register(self, value):
        pass

    @abstractmethod
    def start_collecting(self, alias):
        pass

    @abstractmethod
    def stop_collecting(self, alias):
        pass

    @abstractmethod
    def post_test_cleanup(self):
        pass

    @abstractmethod
    def renew_cellmapping(self):
        pass

    def _check_logs_dir(self, log_dir):
        # type: (str) -> str
        try:
            makedirs(log_dir)
            self.logger.debug('{} created'.format(log_dir))
        except OSError:
            pass
        return log_dir
